update public.listings l
set product_no = c.new_product_no, condition = c.condition, condition_notes = c.condition_notes,
    created_at = c.created_at, sale_started_at = c.created_at, updated_at = now()
from changes c
where l.product_no = c.old_product_no
returning l.id, c.old_product_no, l.product_no, l.condition, l.condition_notes, l.created_at;

